INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g1-num-1-5', 'math-g1-m1', '1-5的认识', '认识数字1到5，理解数量对应关系', 1, '["flashcard","quiz"]', '[]', '[{"type":"flashcard","prompt":"展示{n}个物体（苹果/星星/小动物），让孩子识别数字{n}。范围：1-5。","constraints":{"min":1,"max":5}},{"type":"multiple-choice","prompt":"图片中有几个{object}？请选择正确的数字。选项为3个相邻数字。范围：1-5。","constraints":{"min":1,"max":5,"optionCount":3}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g1-add-within-5', 'math-g1-m1', '5以内加法', '学习5以内的加法运算', 2, '["quiz"]', '["math-g1-num-1-5"]', '[{"type":"multiple-choice","prompt":"计算 {a} + {b} = ?，其中 a 和 b 为正整数，a + b ≤ 5。提供3个选项。","constraints":{"maxSum":5,"optionCount":3}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g1-sub-within-5', 'math-g1-m1', '5以内减法', '学习5以内的减法运算', 2, '["quiz"]', '["math-g1-num-1-5"]', '[{"type":"multiple-choice","prompt":"计算 {a} - {b} = ?，其中 a ≤ 5，b ≤ a。提供3个选项。","constraints":{"maxMinuend":5,"optionCount":3}}]');
