INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-add-within-100', 'math-g2-m1', '100以内加法（进位）', '学习100以内的进位加法', 3, '["quiz"]', '["math-g1-add-within-20"]', '[{"type":"multiple-choice","prompt":"计算 {a} + {b} = ?，其中 a + b ≤ 100，需要进位。提供4个选项。","constraints":{"maxSum":100,"requireCarry":true,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-sub-within-100', 'math-g2-m1', '100以内减法（退位）', '学习100以内的退位减法', 3, '["quiz"]', '["math-g1-sub-within-20"]', '[{"type":"multiple-choice","prompt":"计算 {a} - {b} = ?，其中 a ≤ 100，需要退位。提供4个选项。","constraints":{"maxMinuend":100,"requireBorrow":true,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-add-sub-mixed', 'math-g2-m1', '加减混合运算', '两步以内的加减混合运算', 4, '["quiz"]', '["math-g2-add-within-100","math-g2-sub-within-100"]', '[{"type":"multiple-choice","prompt":"计算 {a} + {b} - {c} = ? 或 {a} - {b} + {c} = ?，结果在100以内。提供4个选项。","constraints":{"maxResult":100,"steps":2,"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('math-g2-m2', 7, '表内乘法', '学习乘法的含义和1-9的乘法口诀', 2);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-multiply-concept', 'math-g2-m2', '乘法的认识', '理解乘法的含义，"几个几"', 3, '["flashcard","quiz"]', '["math-g2-add-within-100"]', '[{"type":"flashcard","prompt":"展示{groups}组，每组{count}个物体，引导理解 {groups}×{count} 的含义。","constraints":{"maxGroups":9,"maxCount":9}},{"type":"multiple-choice","prompt":"{groups}个{count}相加，可以用乘法怎样表示？提供3个选项。","constraints":{"optionCount":3}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-times-table-1-5', 'math-g2-m2', '1-5的乘法口诀', '背诵和运用1-5的乘法口诀', 4, '["flashcard","quiz"]', '["math-g2-multiply-concept"]', '[{"type":"flashcard","prompt":"乘法口诀：{a}×{b}={product}。其中 a, b ∈ [1,5]。","constraints":{"min":1,"max":5}},{"type":"multiple-choice","prompt":"{a} × {b} = ?，其中 a, b ∈ [1,5]。提供4个选项。","constraints":{"min":1,"max":5,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-times-table-6-9', 'math-g2-m2', '6-9的乘法口诀', '背诵和运用6-9的乘法口诀', 5, '["flashcard","quiz"]', '["math-g2-times-table-1-5"]', '[{"type":"flashcard","prompt":"乘法口诀：{a}×{b}={product}。其中至少有一个因数 ∈ [6,9]。","constraints":{"min":1,"max":9,"atLeastOneAbove":5}},{"type":"multiple-choice","prompt":"{a} × {b} = ?，至少一个因数在6-9之间。提供4个选项。","constraints":{"min":1,"max":9,"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('math-g2-m3', 7, '表内除法', '学习除法的含义，用乘法口诀求商', 3);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-divide-concept', 'math-g2-m3', '除法的认识', '理解除法的含义——平均分', 4, '["flashcard","quiz"]', '["math-g2-times-table-1-5"]', '[{"type":"flashcard","prompt":"把{total}个{object}平均分给{groups}个小朋友，每人分几个？引导理解除法。","constraints":{"maxTotal":45}},{"type":"multiple-choice","prompt":"{total} ÷ {divisor} = ?，利用乘法口诀求商。提供4个选项。","constraints":{"maxDividend":81,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-divide-within-table', 'math-g2-m3', '用口诀求商', '运用乘法口诀快速求商', 5, '["quiz"]', '["math-g2-divide-concept","math-g2-times-table-6-9"]', '[{"type":"multiple-choice","prompt":"{a} ÷ {b} = ?，想口诀 {b}×(?)={a}。提供4个选项。","constraints":{"maxDividend":81,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-divide-with-remainder', 'math-g2-m3', '有余数的除法', '理解余数的含义，计算有余数的除法', 5, '["quiz"]', '["math-g2-divide-within-table"]', '[{"type":"multiple-choice","prompt":"{a} ÷ {b} = ? ... ?，求商和余数。注意余数要小于除数。提供4个选项。","constraints":{"maxDividend":50,"hasRemainder":true,"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('math-g2-m4', 7, '万以内数的认识', '认识千位，掌握万以内数的读写和比较', 4);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-num-1000', 'math-g2-m4', '1000以内数的认识', '认识百位和千位，掌握三位数的读写', 4, '["flashcard","quiz"]', '["math-g1-num-100"]', '[{"type":"flashcard","prompt":"用计数器展示{n}，让孩子说出百位、十位、个位分别是什么。范围：100-999。","constraints":{"min":100,"max":999}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-num-10000', 'math-g2-m4', '万以内数的认识', '认识万以内的数，掌握四位数的读写', 5, '["flashcard","quiz"]', '["math-g2-num-1000"]', '[{"type":"flashcard","prompt":"展示数字{n}，让孩子读出来并写出来。范围：1000-9999。注意中间有0的读法。","constraints":{"min":1000,"max":9999}},{"type":"multiple-choice","prompt":"下面哪个数最大/最小？展示4个万以内的数进行比较。","constraints":{"max":9999,"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('math-g2-m5', 7, '长度与时间', '认识厘米和米，认识时间单位', 5);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-length', 'math-g2-m5', '厘米和米', '认识厘米和米，建立长度观念', 3, '["flashcard","quiz"]', '[]', '[{"type":"flashcard","prompt":"展示{object}，估计它大约有多长？选择合适的单位（厘米或米）。","constraints":{"units":["厘米","米"]}},{"type":"multiple-choice","prompt":"1米 = ? 厘米。提供3个选项。","constraints":{"optionCount":3}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-time', 'math-g2-m5', '认识时间', '认识时、分、秒，掌握简单时间计算', 4, '["flashcard","quiz"]', '["math-g1-clock"]', '[{"type":"multiple-choice","prompt":"钟面上显示的是{hour}时{minute}分，用数字怎么表示？提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g2-mass', 'math-g2-m5', '克和千克', '认识克和千克，感受物体的轻重', 3, '["flashcard","quiz"]', '[]', '[{"type":"multiple-choice","prompt":"一个{object}大约重多少？选择合适的答案（用克或千克）。","constraints":{"units":["克","千克"],"optionCount":3}}]');
INSERT INTO api.curricula (id, grade_level, subject, version, reference) VALUES (8, 'grade-2', 'chinese', '2022-v1', '《义务教育语文课程标准（2022年版）》');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('cn-g2-m1', 8, '识字与写字（二年级）', '累计认识1600个常用汉字，书写800个', 1);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-radicals', 'cn-g2-m1', '偏旁部首', '认识常用偏旁部首，利用偏旁归类识字', 3, '["flashcard","quiz"]', '["cn-g1-strokes","cn-g1-stroke-order"]', '[{"type":"flashcard","prompt":"展示偏旁\"{radical}\"，说出它的名称和含义。如：氵（三点水，与水有关）。","constraints":{"category":"radicals"}},{"type":"multiple-choice","prompt":"下面哪个字含有\"{radical}\"偏旁？提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-char-recognition-2', 'cn-g2-m1', '二年级识字', '认识二年级新增的800个常用汉字', 4, '["flashcard","quiz"]', '["cn-g1-char-recognition","cn-g2-radicals"]', '[{"type":"flashcard","prompt":"展示汉字\"{char}\"，标注拼音和偏旁部首，让孩子认读。","constraints":{"level":"grade-2","count":800}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-char-writing-2', 'cn-g2-m1', '二年级写字', '书写二年级新增的400个常用汉字，注意结构', 5, '["writing"]', '["cn-g1-char-writing","cn-g2-char-recognition-2"]', '[{"type":"handwriting","prompt":"请书写汉字：{char}。注意结构（左右/上下/半包围）和占格。","constraints":{"level":"grade-2","count":400}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('cn-g2-m2', 8, '词语积累', '积累词语，学习近义词反义词', 2);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-word-accumulation', 'cn-g2-m2', '词语积累', '积累ABB、AABB、ABAB等形式的词语', 3, '["flashcard","quiz"]', '["cn-g2-char-recognition-2"]', '[{"type":"flashcard","prompt":"学习{pattern}式词语：{word}。如 ABB式：绿油油、白花花。","constraints":{"patterns":["ABB","AABB","ABAB"]}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-synonyms-antonyms', 'cn-g2-m2', '近义词与反义词', '学习常用词语的近义词和反义词', 4, '["quiz"]', '["cn-g2-word-accumulation"]', '[{"type":"multiple-choice","prompt":"\"{word}\"的{type}是什么？选项提供4个词语。类型：近义词/反义词。","constraints":{"types":["近义词","反义词"],"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-measure-words', 'cn-g2-m2', '量词', '正确使用常用量词：一（ ）花、一（ ）书', 3, '["quiz"]', '["cn-g2-word-accumulation"]', '[{"type":"multiple-choice","prompt":"一（ ）{object}，应该填什么量词？提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('cn-g2-m3', 8, '阅读理解（二年级）', '默读课文，学习提问，了解段落', 3);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-silent-reading', 'cn-g2-m3', '默读', '学习默读，不指读，不出声', 3, '["quiz"]', '["cn-g1-reading-aloud"]', '[{"type":"multiple-choice","prompt":"默读以下短文，回答问题：{text}。问题：{question}。提供4个选项。","constraints":{"maxLength":100,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-sequence', 'cn-g2-m3', '了解事情经过', '读懂故事的起因、经过、结果', 4, '["quiz"]', '["cn-g2-silent-reading"]', '[{"type":"multiple-choice","prompt":"阅读故事后，请把事件按顺序排列。故事：{story}。","constraints":{"optionCount":4,"orderType":"sequence"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-questioning', 'cn-g2-m3', '学习提问', '读完课文能提出自己的问题', 5, '["quiz"]', '["cn-g2-sequence"]', '[{"type":"multiple-choice","prompt":"读完这段话后，以下哪个问题最值得讨论？文段：{text}。提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('cn-g2-m4', 8, '写话（二年级）', '能看图写话，写完整的句子', 4);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-complete-sentence', 'cn-g2-m4', '写完整句子', '用"谁在哪里干什么"写完整句子', 4, '["writing"]', '["cn-g1-write-sentence","cn-g2-char-writing-2"]', '[{"type":"handwriting","prompt":"看图写话：观察图片{image}，用\"谁+在哪里+干什么\"的格式写1-2个完整的句子。","constraints":{"minSentences":1,"maxSentences":2,"pattern":"主+地+谓"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g2-picture-writing', 'cn-g2-m4', '看图写话', '观察多幅图写连贯的几句话', 5, '["writing"]', '["cn-g2-complete-sentence"]', '[{"type":"handwriting","prompt":"观察这{count}幅图，写3-5句话描述图中发生的故事。注意使用标点符号。","constraints":{"minSentences":3,"maxSentences":5,"imageCount":4}}]');
