INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-phonics-long-vowels', 'en-g2-m1', '长元音发音', '学习 a_e, i_e, o_e, u_e, ee, ea 等长元音规则', 3, '["voice","flashcard"]', '["en-g1-phonics-cvc"]', '[{"type":"voice","prompt":"单词\"{word}\"中的元音是长元音还是短元音？请跟读。如 cake(长a), cat(短a)。","constraints":{"category":"long-vowels"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-phonics-blends', 'en-g2-m1', '辅音组合', '学习 bl, cl, fl, br, cr, fr, st, sp 等辅音组合', 4, '["voice","flashcard"]', '["en-g1-phonics-consonants"]', '[{"type":"voice","prompt":"请拼读含辅音组合的单词：{word}。如 blue(bl), green(gr), star(st)。","constraints":{"category":"consonant-blends"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-phonics-digraphs', 'en-g2-m1', '字母组合发音', '学习 sh, ch, th, wh, ck 等字母组合的发音', 4, '["voice","quiz"]', '["en-g2-phonics-blends"]', '[{"type":"voice","prompt":"\"{digraph}\"在单词\"{word}\"中发什么音？如 sh-ship, ch-chair, th-think。","constraints":{"category":"digraphs"}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('en-g2-m2', 9, '主题词汇拓展', '学习100个主题词汇（动物、食物、家庭、学校）', 2);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-vocab-animals', 'en-g2-m2', '动物词汇', '学习 cat, dog, bird, fish, rabbit, monkey, elephant 等动物词汇', 2, '["flashcard","voice","quiz"]', '["en-g1-vocab-colors"]', '[{"type":"flashcard","prompt":"展示{animal}的图片和英文\"{word}\"，配合发音。让孩子说：I like {word}s。","constraints":{"category":"animals","count":15}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-vocab-food', 'en-g2-m2', '食物词汇', '学习 apple, banana, cake, milk, rice, bread, egg 等食物词汇', 2, '["flashcard","voice","quiz"]', '["en-g1-vocab-colors"]', '[{"type":"flashcard","prompt":"展示{food}的图片和英文\"{word}\"。引导说：I like {word}. / I don''t like {word}.","constraints":{"category":"food","count":15}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-vocab-family', 'en-g2-m2', '家庭成员词汇', '学习 father, mother, brother, sister, grandpa, grandma 等家庭成员词汇', 2, '["flashcard","quiz"]', '["en-g1-vocab-body"]', '[{"type":"flashcard","prompt":"展示家庭成员图片，教孩子说：This is my {member}。","constraints":{"members":["father","mother","brother","sister","grandpa","grandma"]}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('en-g2-m3', 9, '简单句型', '学习基础句型 I have / I like / It is', 3);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-sentence-i-have', 'en-g2-m3', 'I have... 句型', '学习用 I have... 描述拥有的事物', 3, '["voice","quiz"]', '["en-g2-vocab-animals","en-g2-vocab-food"]', '[{"type":"voice","prompt":"看图说话：I have a {object}. 如 I have a cat. I have two apples.","constraints":{"pattern":"I have + noun"}},{"type":"multiple-choice","prompt":"看图选择正确的句子描述图片内容。提供3个选项。","constraints":{"optionCount":3}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-sentence-i-like', 'en-g2-m3', 'I like... 句型', '学习用 I like... 表达喜好', 3, '["voice","quiz"]', '["en-g2-vocab-animals","en-g2-vocab-food"]', '[{"type":"voice","prompt":"表达你的喜好：I like {noun}. / I don''t like {noun}.","constraints":{"pattern":"I like/don''t like + noun"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-sentence-it-is', 'en-g2-m3', 'It is... 句型', '学习用 It is... 描述事物特征', 3, '["voice","quiz"]', '["en-g1-vocab-colors"]', '[{"type":"voice","prompt":"描述图片中的事物：It is {adjective}. 如 It is big. It is red.","constraints":{"pattern":"It is + adjective"}},{"type":"multiple-choice","prompt":"选择正确的描述：It is ___. 提供3个选项。","constraints":{"optionCount":3}}]');
