INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-dialogue-daily', 'en-g2-m4', '日常对话', '学习购物、问路、点餐等简单场景对话', 4, '["voice","quiz"]', '["en-g2-dialogue-intro","en-g2-sentence-i-like"]', '[{"type":"voice","prompt":"角色扮演：在{scenario}场景中进行对话。A: {lineA} B: {lineB}","constraints":{"scenarios":["购物","问候","点餐"]}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g2-songs-chants', 'en-g2-m4', '英语歌曲与韵文', '学唱英语儿歌，感受韵律', 2, '["voice"]', '["en-g1-greetings"]', '[{"type":"voice","prompt":"跟唱英语儿歌：{song}。注意节奏和发音。","constraints":{"category":"nursery-rhymes"}}]');
INSERT INTO api.curricula (id, grade_level, subject, version, reference) VALUES (10, 'grade-3', 'math', '2022-v1', '《义务教育数学课程标准（2022年版）》');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('math-g3-m1', 10, '万以内加减法', '三位数加减法笔算，连续进位和退位', 1);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-add-3digit', 'math-g3-m1', '三位数加法（连续进位）', '掌握三位数加法笔算，包括连续进位', 4, '["quiz"]', '["math-g2-add-within-100"]', '[{"type":"multiple-choice","prompt":"竖式计算 {a} + {b} = ?，其中 a, b 为三位数。提供4个选项。","constraints":{"min":100,"max":999,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-sub-3digit', 'math-g3-m1', '三位数减法（连续退位）', '掌握三位数减法笔算，包括连续退位', 4, '["quiz"]', '["math-g2-sub-within-100"]', '[{"type":"multiple-choice","prompt":"竖式计算 {a} - {b} = ?，其中 a 为三位数。提供4个选项。","constraints":{"minMinuend":100,"maxMinuend":999,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-estimation', 'math-g3-m1', '估算', '用估算检验计算结果的合理性', 4, '["quiz"]', '["math-g3-add-3digit","math-g3-sub-3digit"]', '[{"type":"multiple-choice","prompt":"{a} + {b} 大约等于多少？用估算法选择最接近的答案。提供4个选项。","constraints":{"optionCount":4,"method":"estimation"}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('math-g3-m2', 10, '多位数乘法与除法', '多位数乘一位数、两三位数除以一位数', 2);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-multiply-1digit', 'math-g3-m2', '多位数乘一位数', '掌握两三位数乘一位数的笔算', 5, '["quiz"]', '["math-g2-times-table-6-9"]', '[{"type":"multiple-choice","prompt":"竖式计算 {a} × {b} = ?，其中 a 为两三位数，b 为一位数。提供4个选项。","constraints":{"maxMultiplicand":999,"maxMultiplier":9,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-divide-1digit', 'math-g3-m2', '两三位数除以一位数', '掌握两三位数除以一位数的笔算', 5, '["quiz"]', '["math-g2-divide-within-table"]', '[{"type":"multiple-choice","prompt":"竖式计算 {a} ÷ {b} = ?，其中 a 为两三位数，b 为一位数。提供4个选项。","constraints":{"maxDividend":999,"maxDivisor":9,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-multiply-2digit', 'math-g3-m2', '两位数乘两位数', '掌握两位数乘两位数的笔算', 6, '["quiz"]', '["math-g3-multiply-1digit"]', '[{"type":"multiple-choice","prompt":"竖式计算 {a} × {b} = ?，其中 a, b 均为两位数。提供4个选项。","constraints":{"min":10,"max":99,"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('math-g3-m3', 10, '分数的初步认识', '认识简单分数，比较同分母分数大小', 3);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-fraction-concept', 'math-g3-m3', '分数的认识', '理解分数的含义，认识分子和分母', 5, '["flashcard","quiz"]', '["math-g3-divide-1digit"]', '[{"type":"flashcard","prompt":"把一个{shape}平均分成{n}份，取其中{m}份，用分数表示为 {m}/{n}。","constraints":{"maxDenominator":10}},{"type":"multiple-choice","prompt":"图中涂色部分用分数怎样表示？提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-fraction-compare', 'math-g3-m3', '分数比大小', '比较同分母分数或同分子分数的大小', 5, '["quiz"]', '["math-g3-fraction-concept"]', '[{"type":"multiple-choice","prompt":"比较 {a}/{c} 和 {b}/{c}，哪个更大？同分母分数比较。提供3个选项。","constraints":{"optionCount":3,"sameDenominator":true}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-fraction-add-sub', 'math-g3-m3', '同分母分数加减法', '计算同分母分数的加法和减法', 6, '["quiz"]', '["math-g3-fraction-compare"]', '[{"type":"multiple-choice","prompt":"计算 {a}/{c} + {b}/{c} = ? 或 {a}/{c} - {b}/{c} = ?，同分母运算。提供4个选项。","constraints":{"maxDenominator":10,"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('math-g3-m4', 10, '图形与测量', '周长的认识与计算，面积的初步认识', 4);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-perimeter', 'math-g3-m4', '周长', '理解周长的含义，计算长方形和正方形的周长', 4, '["quiz"]', '["math-g1-shapes-2d","math-g3-add-3digit"]', '[{"type":"multiple-choice","prompt":"长方形的长是{length}厘米，宽是{width}厘米，周长是多少厘米？提供4个选项。","constraints":{"maxSide":50,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-area-concept', 'math-g3-m4', '面积的认识', '理解面积的含义，认识平方厘米、平方分米、平方米', 5, '["flashcard","quiz"]', '["math-g3-perimeter"]', '[{"type":"flashcard","prompt":"展示1平方{unit}的大小，让孩子感受面积单位。单位：厘米/分米/米。","constraints":{"units":["厘米","分米","米"]}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g3-area-rect', 'math-g3-m4', '长方形和正方形的面积', '计算长方形和正方形的面积', 5, '["quiz"]', '["math-g3-area-concept","math-g3-multiply-1digit"]', '[{"type":"multiple-choice","prompt":"长方形的长是{length}厘米，宽是{width}厘米，面积是多少平方厘米？提供4个选项。","constraints":{"maxSide":30,"optionCount":4}}]');
