INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g3-dictionary', 'cn-g3-m1', '查字典', '学习使用音序查字法和部首查字法', 4, '["quiz"]', '["cn-g2-radicals"]', '[{"type":"multiple-choice","prompt":"用部首查字法查\"{char}\"字，应该先查什么部首，再查几画？提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g3-char-recognition-3', 'cn-g3-m1', '三年级识字', '认识三年级新增的约900个汉字', 5, '["flashcard","quiz"]', '["cn-g2-char-recognition-2","cn-g3-dictionary"]', '[{"type":"flashcard","prompt":"展示汉字\"{char}\"，标注拼音、部首和组词。","constraints":{"level":"grade-3"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g3-char-writing-3', 'cn-g3-m1', '三年级写字', '书写三年级新增的约800个汉字，注意间架结构', 5, '["writing"]', '["cn-g2-char-writing-2","cn-g3-char-recognition-3"]', '[{"type":"handwriting","prompt":"请书写汉字：{char}。注意间架结构和笔画穿插。","constraints":{"level":"grade-3"}}]');
