INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g3-key-words', 'cn-g3-m2', '体会关键词句', '找出文中关键词句，体会作者表达的意思', 5, '["quiz"]', '["cn-g2-questioning"]', '[{"type":"multiple-choice","prompt":"文中\"{sentence}\"这句话说明了什么？提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g3-retell', 'cn-g3-m2', '复述故事', '能用自己的话复述课文的主要内容', 5, '["voice","quiz"]', '["cn-g3-key-words"]', '[{"type":"voice","prompt":"请用自己的话复述这个故事的主要内容。故事：{story}。","constraints":{"maxLength":200}},{"type":"multiple-choice","prompt":"下面哪个选项最能概括这个故事的主要内容？提供4个选项。","constraints":{"optionCount":4}}]');
