INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g3-imagination', 'cn-g3-m3', '想象作文', '发挥想象写一个故事', 6, '["writing"]', '["cn-g3-retell","cn-g3-observation"]', '[{"type":"handwriting","prompt":"以\"{opening}\"为开头，发挥想象，续写一个有趣的故事。不少于150字。","constraints":{"minWords":150,"format":"story"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g3-punctuation', 'cn-g3-m3', '标点符号运用', '正确使用逗号、句号、问号、感叹号、冒号、引号', 4, '["quiz"]', '["cn-g2-complete-sentence"]', '[{"type":"multiple-choice","prompt":"给下面的句子加上正确的标点符号：{sentence}。提供4个选项。","constraints":{"marks":["，","。","？","！","：","\""],"optionCount":4}}]');
