INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g3-letter-sounds', 'en-g3-m1', '字母在单词中的发音', '系统掌握每个字母在常见单词中的发音', 3, '["voice","quiz"]', '["en-g2-phonics-long-vowels"]', '[{"type":"voice","prompt":"字母\"{letter}\"在以下单词中的发音：{word1}, {word2}, {word3}。请跟读。","constraints":{"category":"letter-sounds"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g3-sight-words', 'en-g3-m1', '高频词（Sight Words）', '掌握100个一级高频词：the, is, are, have, can 等', 3, '["flashcard","quiz"]', '["en-g2-phonics-digraphs"]', '[{"type":"flashcard","prompt":"认读高频词：{word}。在句子中练习：{sentence}。","constraints":{"level":1,"count":100}}]');
