INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g3-vocab-school', 'en-g3-m2', '学校相关词汇', '学习 classroom, teacher, student, desk, chair, pencil, eraser 等学校词汇', 3, '["flashcard","quiz"]', '["en-g2-vocab-animals","en-g2-vocab-food"]', '[{"type":"flashcard","prompt":"展示{item}的图片和英文\"{word}\"。引导造句：There is a {word} in the classroom.","constraints":{"category":"school","count":20}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g3-vocab-weather', 'en-g3-m2', '天气词汇', '学习 sunny, rainy, cloudy, windy, snowy, hot, cold 等天气词汇', 3, '["flashcard","quiz"]', '["en-g2-vocab-animals"]', '[{"type":"flashcard","prompt":"展示{weather}的图片和英文\"{word}\"。练习：It is {word} today.","constraints":{"category":"weather"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g3-vocab-actions', 'en-g3-m2', '动作词汇', '学习 run, jump, swim, read, write, sing, dance, eat, drink 等动作词汇', 3, '["flashcard","voice"]', '["en-g1-classroom"]', '[{"type":"flashcard","prompt":"展示动作图片和英文\"{word}\"。练习：I can {word}.","constraints":{"category":"actions","count":20}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('en-g3-m3', 12, '基础句型与语法', '学习 be 动词、can、一般疑问句', 3);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g3-be-verb', 'en-g3-m3', 'be 动词用法', '学习 I am / You are / He is / She is / It is / We are / They are', 4, '["quiz"]', '["en-g2-sentence-it-is"]', '[{"type":"multiple-choice","prompt":"选择正确的 be 动词填空：{subject} ___ {adjective/noun}. 提供3个选项（am/is/are）。","constraints":{"optionCount":3}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g3-can', 'en-g3-m3', 'can 句型', '学习用 can/can''t 表达能力：I can swim. Can you dance?', 4, '["voice","quiz"]', '["en-g3-vocab-actions"]', '[{"type":"voice","prompt":"用 can 造句：I can {action}. / I can''t {action}. / Can you {action}?","constraints":{"pattern":"can + verb"}},{"type":"multiple-choice","prompt":"看图回答：Can he/she {action}? Yes, he/she can. / No, he/she can''t. 提供2个选项。","constraints":{"optionCount":2}}]');
