INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g3-writing-sentence', 'en-g3-m4', '仿写句子', '仿照例句写简单的英文句子', 5, '["writing"]', '["en-g3-be-verb","en-g3-can"]', '[{"type":"handwriting","prompt":"仿照例句写一个句子。例句：{example}。请写一个类似的句子。","constraints":{"pattern":"imitation"}}]');
