INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g4-add-laws', 'math-g4-m2', '加法运算律', '掌握加法交换律和结合律，运用简便计算', 5, '["quiz"]', '["math-g3-add-3digit"]', '[{"type":"multiple-choice","prompt":"用简便方法计算：{expression}。提示：运用加法交换律或结合律。提供4个选项。","constraints":{"laws":["交换律","结合律"],"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g4-multiply-laws', 'math-g4-m2', '乘法运算律', '掌握乘法交换律、结合律和分配律', 6, '["quiz"]', '["math-g4-multiply-3by2"]', '[{"type":"multiple-choice","prompt":"用简便方法计算：{expression}。提示：运用乘法分配律。提供4个选项。","constraints":{"laws":["交换律","结合律","分配律"],"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g4-four-operations', 'math-g4-m2', '四则混合运算', '掌握含括号的四则混合运算顺序', 6, '["quiz"]', '["math-g4-add-laws","math-g4-multiply-laws"]', '[{"type":"multiple-choice","prompt":"按正确顺序计算：{expression}。注意先乘除后加减，有括号先算括号。提供4个选项。","constraints":{"operations":3,"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('math-g4-m3', 13, '小数', '小数的意义和性质，小数加减法', 3);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g4-decimal-concept', 'math-g4-m3', '小数的意义', '理解小数的意义，掌握小数的读写和比较', 5, '["flashcard","quiz"]', '["math-g3-fraction-concept"]', '[{"type":"flashcard","prompt":"0.{n} 表示十分之{n}，0.0{m} 表示百分之{m}。用图形展示小数的含义。","constraints":{"maxDecimalPlaces":2}},{"type":"multiple-choice","prompt":"比较 {a} 和 {b} 的大小（两个小数）。提供3个选项（>、=、<）。","constraints":{"optionCount":3}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g4-decimal-add-sub', 'math-g4-m3', '小数加减法', '掌握小数加法和减法的笔算方法', 6, '["quiz"]', '["math-g4-decimal-concept"]', '[{"type":"multiple-choice","prompt":"竖式计算 {a} + {b} = ? 或 {a} - {b} = ?（小数运算，注意小数点对齐）。提供4个选项。","constraints":{"maxDecimalPlaces":2,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g4-decimal-multiply', 'math-g4-m3', '小数乘法', '掌握小数乘整数和小数乘小数', 7, '["quiz"]', '["math-g4-decimal-add-sub","math-g4-multiply-3by2"]', '[{"type":"multiple-choice","prompt":"计算 {a} × {b} = ?（至少一个是小数）。注意确定积的小数点位置。提供4个选项。","constraints":{"maxDecimalPlaces":2,"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('math-g4-m4', 13, '图形与角', '角的度量，平行四边形和梯形', 4);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g4-angle', 'math-g4-m4', '角的度量', '认识量角器，测量和画指定度数的角', 5, '["flashcard","quiz"]', '["math-g3-perimeter"]', '[{"type":"flashcard","prompt":"这个角是多少度？用量角器测量。角的类型：锐角(<90°)/直角(90°)/钝角(>90°)/平角(180°)。","constraints":{"maxDegree":180}},{"type":"multiple-choice","prompt":"一个角是{degree}度，它是什么角？提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g4-parallel-perpendicular', 'math-g4-m4', '平行与垂直', '认识平行线和垂线，掌握画法', 5, '["flashcard","quiz"]', '["math-g4-angle"]', '[{"type":"multiple-choice","prompt":"下面哪组线是互相平行的？哪组是互相垂直的？提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g4-quadrilateral', 'math-g4-m4', '平行四边形和梯形', '认识平行四边形和梯形的特征', 5, '["flashcard","quiz"]', '["math-g4-parallel-perpendicular"]', '[{"type":"multiple-choice","prompt":"下面哪个图形是平行四边形/梯形？说出它的特征。提供4个选项。","constraints":{"shapes":["平行四边形","梯形","长方形","正方形"],"optionCount":4}}]');
