INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('math-g5-cuboid-volume', 'math-g5-m4', '长方体和正方体体积', '认识体积单位，计算长方体和正方体的体积', 7, '["quiz"]', '["math-g5-parallelogram-area","math-g5-decimal-multiply"]', '[{"type":"multiple-choice","prompt":"长方体长 {l}cm，宽 {w}cm，高 {h}cm，体积是多少立方厘米？提供4个选项。","constraints":{"maxSide":20,"optionCount":4}}]');
