INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g5-speed-reading', 'cn-g5-m1', '提高阅读速度', '用较快速度默读，每分钟不少于300字', 5, '["quiz"]', '["cn-g4-main-idea"]', '[{"type":"multiple-choice","prompt":"快速阅读以下文章（约300字），回答问题。{text}。问题：{question}。提供4个选项。","constraints":{"wordsPerMinute":300,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g5-extract-info', 'cn-g5-m1', '提取关键信息', '从文章中提取关键信息，列出要点', 6, '["quiz"]', '["cn-g5-speed-reading"]', '[{"type":"multiple-choice","prompt":"阅读短文，下列哪项是文中提到的关键信息？{text}。提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g5-expression-method', 'cn-g5-m1', '体会表达方法', '体会比喻、拟人、排比等修辞手法的效果', 7, '["quiz"]', '["cn-g4-character-feeling"]', '[{"type":"multiple-choice","prompt":"\"{sentence}\"运用了什么修辞手法？有什么表达效果？提供4个选项。","constraints":{"methods":["比喻","拟人","排比","夸张"],"optionCount":4}}]');
