INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g5-descriptive-writing', 'cn-g5-m2', '写景状物', '学习描写景物，运用修辞手法使文章生动', 7, '["writing"]', '["cn-g4-narrative","cn-g5-expression-method"]', '[{"type":"handwriting","prompt":"以\"{title}\"为题，写一篇写景文。要求：运用比喻或拟人手法，按一定顺序描写。不少于300字。","constraints":{"minWords":300,"format":"descriptive"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g5-narrative-detail', 'cn-g5-m2', '记叙文细节描写', '学习通过动作、语言、心理描写刻画人物', 7, '["writing"]', '["cn-g4-narrative","cn-g4-character-feeling"]', '[{"type":"handwriting","prompt":"写一个你印象深刻的人。要求：通过一两件事表现人物特点，注意动作和语言描写。不少于300字。","constraints":{"minWords":300,"format":"narrative-with-detail"}}]');
