INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g6-argumentative', 'cn-g6-m2', '简单议论', '学习表达自己的观点并说明理由', 8, '["writing"]', '["cn-g5-narrative-detail","cn-g6-critical-reading"]', '[{"type":"handwriting","prompt":"对于\"{topic}\"，你怎么看？请写出你的观点，并用2-3个理由支持。不少于300字。","constraints":{"minWords":300,"format":"argumentative"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g6-book-review', 'cn-g6-m2', '读后感', '写读后感，表达阅读感受和思考', 7, '["writing"]', '["cn-g6-critical-reading","cn-g5-revision"]', '[{"type":"handwriting","prompt":"读完《{book}》后，写一篇读后感。要求：简介内容+深入感受+联系实际。不少于350字。","constraints":{"minWords":350,"format":"book-review"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g6-creative-writing', 'cn-g6-m2', '创意写作', '发挥想象，写科幻故事或童话', 8, '["writing"]', '["cn-g5-descriptive-writing","cn-g6-argumentative"]', '[{"type":"handwriting","prompt":"以\"{opening}\"为开头，写一个{genre}故事。要求情节完整、想象丰富。不少于400字。","constraints":{"minWords":400,"genres":["科幻","童话","冒险"],"format":"creative"}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('cn-g6-m3', 20, '综合素养', '古文阅读、口语交际、信息整合', 3);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g6-classical-chinese', 'cn-g6-m3', '简单文言文阅读', '借助注释理解简单的文言文', 7, '["quiz"]', '["cn-g5-ancient-poetry"]', '[{"type":"multiple-choice","prompt":"阅读文言文：{text}。\"{word}\"在文中的意思是什么？提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g6-oral-expression', 'cn-g6-m3', '口语交际', '能围绕话题有条理地表达观点', 6, '["voice"]', '["cn-g5-extract-info"]', '[{"type":"voice","prompt":"请围绕\"{topic}\"发表你的看法，说清楚你的观点和理由（1-2分钟）。","constraints":{"maxMinutes":2}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('cn-g6-info-integration', 'cn-g6-m3', '信息整合', '综合多种材料提取和整合信息', 8, '["quiz"]', '["cn-g5-extract-info","cn-g6-critical-reading"]', '[{"type":"multiple-choice","prompt":"阅读以下两则材料，{material_a} 和 {material_b}，综合判断以下哪个结论正确。提供4个选项。","constraints":{"materialCount":2,"optionCount":4}}]');
INSERT INTO api.curricula (id, grade_level, subject, version, reference) VALUES (21, 'grade-6', 'english', '2022-v1', '《义务教育英语课程标准（2022年版）》2级');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('en-g6-m1', 21, '词汇巩固（600+词）', '巩固和拓展核心词汇至600词以上', 1);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g6-vocab-600', 'en-g6-m1', '核心词汇巩固', '巩固600个核心词汇，学习词性变化和词组搭配', 6, '["flashcard","quiz"]', '["en-g5-vocab-daily","en-g5-vocab-adjective"]', '[{"type":"multiple-choice","prompt":"选择正确的词填空：{sentence}。提供4个选项。","constraints":{"level":2,"count":600,"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g6-word-formation', 'en-g6-m1', '构词法初步', '了解常见前缀 un-/re- 和后缀 -er/-ly/-ful 的含义', 6, '["quiz"]', '["en-g5-vocab-adjective"]', '[{"type":"multiple-choice","prompt":"加上前缀/后缀后单词的意思：un+happy=unhappy(不高兴)。{word}+{affix}=? 提供4个选项。","constraints":{"prefixes":["un-","re-"],"suffixes":["-er","-ly","-ful"],"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('en-g6-m2', 21, '语法综合', '一般将来时、比较级最高级、综合时态运用', 2);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g6-future-tense', 'en-g6-m2', '一般将来时', '学习 will/be going to 表达将来计划', 7, '["quiz"]', '["en-g5-past-tense"]', '[{"type":"multiple-choice","prompt":"用一般将来时填空：I ___ (visit) my grandpa next Sunday. 提供4个选项。","constraints":{"optionCount":4,"tense":"future"}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g6-comparative', 'en-g6-m2', '比较级与最高级', '学习形容词的比较级和最高级：taller, tallest; more beautiful, most beautiful', 6, '["quiz"]', '["en-g5-vocab-adjective"]', '[{"type":"multiple-choice","prompt":"{adjective} 的比较级/最高级是什么？/ Tom is ___ than Jack. 提供4个选项。","constraints":{"optionCount":4,"rules":["-er/-est","more/most","irregular"]}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g6-tense-review', 'en-g6-m2', '综合时态运用', '综合运用一般现在时、现在进行时、一般过去时、一般将来时', 8, '["quiz"]', '["en-g6-future-tense","en-g5-past-tense","en-g5-present-continuous"]', '[{"type":"multiple-choice","prompt":"根据时间状语选择正确时态填空：{sentence}。提供4个选项。","constraints":{"tenses":["present","present-continuous","past","future"],"optionCount":4}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('en-g6-m3', 21, '阅读与写作', '200词短文阅读，写80-100词短文', 3);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g6-reading-200', 'en-g6-m3', '短文阅读理解', '阅读150-200词的英文短文，理解主旨、细节和推理', 7, '["quiz"]', '["en-g5-reading-150","en-g6-tense-review"]', '[{"type":"multiple-choice","prompt":"Read the passage and answer: {passage}。Question: {question}。提供4个选项。","constraints":{"maxWords":200,"questionTypes":["main-idea","detail","inference"],"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g6-writing-100', 'en-g6-m3', '短文写作（80-100词）', '围绕主题写80-100词的英文短文', 7, '["writing"]', '["en-g5-composition","en-g6-tense-review"]', '[{"type":"handwriting","prompt":"以 \"{topic}\" 为题写一篇80-100词的英文短文。要求：语法正确，条理清晰，时态恰当。","constraints":{"minWords":80,"maxWords":100}}]');
INSERT INTO api.curriculum_modules (id, curriculum_id, name, description, order_index) VALUES ('en-g6-m4', 21, '综合语言运用', '小升初衔接，综合听说读写', 4);
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g6-comprehensive-listening', 'en-g6-m4', '综合听力理解', '听懂日常对话和简短独白，获取关键信息', 7, '["voice","quiz"]', '["en-g5-wh-questions","en-g6-tense-review"]', '[{"type":"multiple-choice","prompt":"听对话/独白，回答问题。Audio: {audio_description}。Question: {question}。提供4个选项。","constraints":{"optionCount":4}}]');
INSERT INTO api.curriculum_nodes (id, module_id, name, description, difficulty, content_types, prerequisites, template_prompts) VALUES ('en-g6-oral-presentation', 'en-g6-m4', '口语表达', '围绕话题进行简短的口头表达（1-2分钟）', 7, '["voice"]', '["en-g6-comprehensive-listening","en-g6-comparative"]', '[{"type":"voice","prompt":"请用1-2分钟介绍 \"{topic}\"。包含：描述、感受和原因。","constraints":{"maxMinutes":2}}]');
